    reduce("html { --v: calc(1 + 1); line-height: min(3, 30px) } body { font-size: 32px } #b { font-size: 32px; --v: calc(100% + 1px); line-height: revert-layer } #c { font-size: 32px; --v: 2rlh } #a { font-size: 24px }");
    TEST_ASSERT_EQUAL_STRING("15 20 20", h3());
    reduce("#a { font-size: 16px } #c { font-size: 16px; line-height: calc(1 + 0.25) } body { --v: 150%; line-height: min(3, 30px) } html { line-height: calc(1rlh + 5px) }");
    TEST_ASSERT_EQUAL_STRING("15 15 20", h3());
    reduce("#a { font-size: 16px; line-height: 1.5 } #b { line-height: max(100%, 1rlh) } body { line-height: revert }");
