    TEST_ASSERT_EQUAL_STRING("25 24 40", h3());
    reduce("@layer a { html { line-height: normal } } #c { line-height: 0.5 } #a { font-size: 12px } body { font-size: 16px; --v: 1.5 } #b { line-height: 1.5 }");
